const candidates = $json.candidates || [];
const firstCandidate = candidates[0] || {};
const content = firstCandidate.content || {};
const parts = content.parts || [];
// Ambil semua bagian teks (abaikan bagian 'thought' bila ada), bukan hanya parts[0]
const text = parts.filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('');

const cleaned = text.replace(/```json|```/g, '').trim();
let parsed = [];
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = [];
}

if (!Array.isArray(parsed)) {
  parsed = (typeof parsed === 'object' && parsed !== null) ? [parsed] : [];
}

// Domain dinormalkan huruf kecil supaya cocok dengan key antrean (queue_<domain>)
// dan dengan pencarian di dashboard. last_verified/timestamp dibaca dashboard & backend Go.
const nowIso = new Date().toISOString();
return parsed
  .filter(p => p && typeof p.domain === 'string' && p.domain.trim() !== '')
  .map(p => ({ json: { ...p, domain: p.domain.toLowerCase().trim(), last_verified: nowIso, timestamp: nowIso } }));

// Node Redis operasi "keys" TIDAK mengembalikan properti `keys`.
// Bentuk keluarannya bergantung versi/opsi: {"queue_a.com":"a.com"} atau {"queue_*":[...]}.
// Fungsi ini menerima semua bentuk itu dan mengembalikan Set nama key.
function collectKeys(items, prefix) {
  const out = new Set();
  const add = (v) => { if (typeof v === 'string' && v.startsWith(prefix) && !v.includes('*')) out.add(v); };
  for (const it of items) {
    const j = (it && it.json) || {};
    for (const [prop, val] of Object.entries(j)) {
      add(prop);
      if (Array.isArray(val)) val.forEach(add); else add(val);
    }
  }
  return out;
}

// Batasi per jalan agar balasan Gemini tidak terpotong. Sisanya diproses pada Cron berikutnya.
const MAX_PER_RUN = 40;

const keys = [...collectKeys($input.all(), 'queue_')].sort();

// Antrean kosong itu normal: workflow berhenti di sini tanpa error.
return keys.slice(0, MAX_PER_RUN).map(key => ({ json: { key } }));

// Gabungkan SEMUA domain yang menunggu (dari banyak batch webhook) menjadi
// SATU pesan per client, dikelompokkan per group. Maks MAX_PER_GROUP domain tampil per group.
const MAX_PER_GROUP = 10;
const byClient = new Map();
const seen = new Set();

for (const it of $input.all()) {
  let r = it.json.value;
  try { if (typeof r === 'string') r = JSON.parse(r); } catch (e) { continue; }
  if (!r || !r.domain || !r.client_ip) continue;

  const uniq = r.client_ip + '|' + r.domain;
  if (seen.has(uniq)) continue;
  seen.add(uniq);

  const c = byClient.get(r.client_ip) || { client_ip: r.client_ip, aps: new Set(), groups: new Map(), entries: [] };
  if (r.ap_name) c.aps.add(r.ap_name);
  const list = c.groups.get(r.group || 'Unknown') || [];
  list.push(r.domain);
  c.groups.set(r.group || 'Unknown', list);
  c.entries.push({ domain: r.domain, client_ip: r.client_ip });
  byClient.set(r.client_ip, c);
}

return [...byClient.values()].map(c => {
  let text = `:warning: *Blacklist Alert*\nClient \`${c.client_ip}\` | AP: *${[...c.aps].join(', ') || '-'}* | ${c.entries.length} domain baru`;
  for (const [group, domains] of c.groups) {
    text += `\n\n*${group}* (${domains.length})`;
    domains.slice(0, MAX_PER_GROUP).forEach(dom => { text += `\n\u2022 \`${dom}\``; });
    if (domains.length > MAX_PER_GROUP) {
      text += `\n\u2022 \u2026dan ${domains.length - MAX_PER_GROUP} domain lainnya (lihat dashboard)`;
    }
  }
  return { json: { text, client_ip: c.client_ip, total: c.entries.length, entries: c.entries } };
});

// Node Redis operasi "keys" bentuk keluarannya bervariasi; fungsi ini menerima semua bentuk.
function collectKeys(items, prefix) {
  const out = new Set();
  const add = (v) => { if (typeof v === 'string' && v.startsWith(prefix) && !v.includes('*')) out.add(v); };
  for (const it of items) {
    const j = (it && it.json) || {};
    for (const [prop, val] of Object.entries(j)) {
      add(prop);
      if (Array.isArray(val)) val.forEach(add); else add(val);
    }
  }
  return out;
}

const pending = collectKeys($('Flush: Redis Keys pending').all(), 'slack_pending_');
const sent = collectKeys($('Flush: Redis Keys sent').all(), 'slack_sent_');

// Lewati entri yang ternyata sudah terkirim (mencegah dobel karena race antar eksekusi)
const keys = [...pending].sort().filter(k => !sent.has('slack_sent_' + k.slice('slack_pending_'.length)));

// Antrean kosong itu normal: workflow berhenti di sini tanpa error.
return keys.map(key => ({ json: { key } }));

// Jalan hanya SETELAH Slack sukses. Pecah kembali jadi satu item per (domain, client)
// untuk ditandai terkirim dan dihapus dari antrean.
const out = [];
for (const it of $('Group per Client (Code - JS)').all()) {
  for (const e of (it.json.entries || [])) out.push({ json: e });
}
return out;

// Simpan payload webhook apa adanya (data mentah) untuk arsip jangka panjang.
const body = $input.first().json.body;
const now = new Date();
const wibDate = new Date(now.getTime() + 7 * 3600 * 1000).toISOString().slice(0, 10);
return [{ json: {
  received_at: now.toISOString(),
  date: wibDate,
  source: 'webhook:dns-scan-webhook',
  row_count: Array.isArray(body) ? body.length : (body ? 1 : 0),
  payload: body === undefined ? null : body,
} }];

// ===== Konfigurasi =====
const TZ_OFFSET_MIN = 7 * 60;  // WIB = UTC+7
const HIST_DAYS = 7;           // pembanding: rata-rata N hari sebelumnya
// =======================
const pad = n => String(n).padStart(2, '0');
const fmt = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;

// Cron (malam) -> laporan KEMARIN yang sudah lengkap.
// Manual / test -> HARI INI sampai saat ini (data sementara).
const isTest = $execution.mode === 'test';
const nowWib = new Date(Date.now() + TZ_OFFSET_MIN * 60000);
const target = new Date(Date.UTC(nowWib.getUTCFullYear(), nowWib.getUTCMonth(), nowWib.getUTCDate() - (isTest ? 0 : 1)));
const fromMs = target.getTime() - TZ_OFFSET_MIN * 60000;   // 00:00 WIB dalam UTC
const from = new Date(fromMs).toISOString();
const to = new Date(fromMs + 86400000).toISOString();
const date = fmt(target);
const histFrom = fmt(new Date(target.getTime() - HIST_DAYS * 86400000));

// Pipeline agregasi untuk koleksi ip_access_dns.
// $convert membuat filter tanggal tetap jalan baik `timestamp` tersimpan sebagai string ISO maupun Date.
const blHits = { $sum: { $cond: [{ $eq: ['$inBlacklist', true] }, '$cnt', 0] } };
const pipeline = [
  { $addFields: {
      ts: { $convert: { input: '$timestamp', to: 'date', onError: null, onNull: null } },
      cnt: { $ifNull: ['$access_count', 1] },
      ap: { $ifNull: ['$ap_name', ''] },
  } },
  { $match: { $expr: { $and: [
      { $gte: ['$ts', { $toDate: from }] },
      { $lt: ['$ts', { $toDate: to }] },
  ] } } },
  { $facet: {
      overall: [
        { $group: { _id: null, total: { $sum: '$cnt' }, rows: { $sum: 1 }, clients: { $addToSet: '$client_ip' }, blacklist_hits: blHits } },
        { $project: { _id: 0, total: 1, rows: 1, blacklist_hits: 1, unique_clients: { $size: '$clients' } } },
      ],
      by_ap: [
        { $group: { _id: '$ap', total: { $sum: '$cnt' }, clients: { $addToSet: '$client_ip' }, blacklist_hits: blHits } },
        { $project: { total: 1, blacklist_hits: 1, unique_clients: { $size: '$clients' } } },
      ],
      by_group: [
        { $group: { _id: { group: '$group', type: '$type' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 40 },
      ],
      by_ap_group: [
        { $group: { _id: { ap: '$ap', group: '$group', type: '$type' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 600 },
      ],
      by_ap_domain: [
        { $group: { _id: { ap: '$ap', domain: '$domain', group: '$group' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 4000 },
      ],
      top_clients: [
        { $group: { _id: { client_ip: '$client_ip', ap: '$ap' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 10 },
      ],
      blacklist_events: [
        { $match: { inBlacklist: true } },
        { $group: { _id: { client_ip: '$client_ip', ap: '$ap', domain: '$domain', group: '$group' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 50 },
      ],
  } },
];

return [{ json: { date, partial: isTest, from, to, hist_from: histFrom, hist_days: HIST_DAYS, pipeline: JSON.stringify(pipeline) } }];

// Ubah hasil agregasi Mongo (satu dokumen $facet) menjadi dokumen statistik harian yang ringkas.
const cfg = $('Report: Date Range').first().json;
const f = ($input.first() && $input.first().json) || {};
const arr = k => (Array.isArray(f[k]) ? f[k] : []);
const num = v => (typeof v === 'number' && isFinite(v) ? v : 0);
const AP = a => (a && String(a).trim()) || 'Unknown AP';
const GRP = g => (g && String(g).trim()) || 'Unknown';

// Domain induk (registrable domain): cdn.tiktokv.com -> tiktokv.com ; a.b.co.id -> b.co.id
const SLD = new Set(['co.id', 'or.id', 'ac.id', 'go.id', 'web.id', 'sch.id', 'my.id', 'biz.id', 'mil.id', 'com.au', 'co.uk', 'com.sg', 'co.jp', 'com.br', 'co.in', 'com.my']);
const root = d => {
  const p = String(d).toLowerCase().split('.').filter(Boolean);
  if (p.length <= 2) return p.join('.');
  return SLD.has(p.slice(-2).join('.')) ? p.slice(-3).join('.') : p.slice(-2).join('.');
};

const per = new Map();
const ap = name => {
  if (!per.has(name)) per.set(name, { ap_name: name, total: 0, unique_clients: 0, blacklist_hits: 0, groups: [], domains: [] });
  return per.get(name);
};

for (const r of arr('by_ap')) {
  const e = ap(AP(r._id));
  e.total += num(r.total);
  e.unique_clients = Math.max(e.unique_clients, num(r.unique_clients));
  e.blacklist_hits += num(r.blacklist_hits);
}
for (const r of arr('by_ap_group')) {
  const id = r._id || {};
  ap(AP(id.ap)).groups.push({ group: GRP(id.group), type: id.type || 'unknown', total: num(r.total) });
}
const rolled = new Map();
for (const r of arr('by_ap_domain')) {
  const id = r._id || {};
  const a = AP(id.ap);
  const rd = root(id.domain || '');
  if (!rd) continue;
  const k = a + '||' + rd;
  const cur = rolled.get(k) || { ap: a, domain: rd, group: GRP(id.group), total: 0, top: 0 };
  const t = num(r.total);
  cur.total += t;
  if (t > cur.top) { cur.top = t; cur.group = GRP(id.group); }
  rolled.set(k, cur);
}
for (const v of rolled.values()) ap(v.ap).domains.push({ domain: v.domain, group: v.group, total: v.total });

const byTotal = (a, b) => b.total - a.total;
const per_ap = [...per.values()].map(e => ({
  ...e,
  groups: e.groups.sort(byTotal).slice(0, 15),
  domains: e.domains.sort(byTotal).slice(0, 40),
})).sort(byTotal);

const o = arr('overall')[0] || {};
const stats = {
  date: cfg.date,
  partial: !!cfg.partial,
  generated_at: new Date().toISOString(),
  total_requests: num(o.total),
  unique_clients: num(o.unique_clients),
  rows: num(o.rows),
  blacklist_hits: num(o.blacklist_hits),
  by_group: arr('by_group').map(r => ({ group: GRP((r._id || {}).group), type: (r._id || {}).type || 'unknown', total: num(r.total) })),
  per_ap,
  top_clients: arr('top_clients').map(r => ({ client_ip: (r._id || {}).client_ip || '-', ap_name: AP((r._id || {}).ap), total: num(r.total) })),
  blacklist_events: arr('blacklist_events').map(r => {
    const id = r._id || {};
    return { client_ip: id.client_ip || '-', ap_name: AP(id.ap), domain: id.domain || '-', group: GRP(id.group), total: num(r.total) };
  }),
};
const has_data = stats.total_requests > 0;

const HARI = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const BULAN = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
const [y, m, d] = cfg.date.split('-').map(Number);
const label = `${HARI[new Date(Date.UTC(y, m - 1, d)).getUTCDay()]}, ${d} ${BULAN[m - 1]} ${y}`;

const slack_text = has_data ? '' :
  `:warning: *Laporan Harian SATA — ${label}*\n` +
  'Tidak ada data DNS untuk tanggal ini di koleksi `ip_access_dns`, jadi laporan tidak dibuat.\n' +
  'Periksa: (1) Vector/webhook masih mengirim log, (2) field `timestamp` di `ip_access_dns` berformat tanggal yang bisa dibaca (ISO 8601).';

return [{ json: { ...stats, has_data, slack_text } }];

// ===== Konfigurasi tren =====
const MIN_VOLUME = 50;   // abaikan entri dengan request terlalu sedikit
const PCT_UP = 30;       // dianggap naik signifikan bila >= 30% di atas rata-rata
const PCT_DOWN = 30;     // dianggap turun signifikan bila >= 30% di bawah rata-rata
const TOP_UP = 8, TOP_DOWN = 5, TOP_NEW = 5;
// ============================
const today = $('Report: Build Daily Stats').first().json;
const hist = $input.all().map(i => i.json)
  .filter(d => d && d.date && Array.isArray(d.per_ap))
  .sort((a, b) => String(a.date).localeCompare(String(b.date)));
const n = hist.length;

// key -> { value, group }
const mapOf = (doc, kind) => {
  const m = new Map();
  for (const a of doc.per_ap || []) {
    if (kind === 'ap') m.set(a.ap_name, { value: a.total || 0 });
    if (kind === 'group') for (const g of a.groups || []) {
      const k = a.ap_name + '||' + g.group;
      m.set(k, { value: ((m.get(k) || {}).value || 0) + (g.total || 0) });
    }
    if (kind === 'domain') for (const d of a.domains || []) m.set(a.ap_name + '||' + d.domain, { value: d.total || 0, group: d.group });
  }
  return m;
};

function compare(kind) {
  const tm = mapOf(today, kind);
  const hm = hist.map(d => mapOf(d, kind));
  const keys = new Set(tm.keys());
  for (const m of hm) for (const k of m.keys()) keys.add(k);
  const rows = [];
  for (const k of keys) {
    const t = (tm.get(k) || { value: 0 }).value;
    let sum = 0;
    for (const m of hm) sum += (m.get(k) || { value: 0 }).value;
    const avg = n ? sum / n : 0;
    const meta = tm.get(k) || hm.map(m => m.get(k)).find(Boolean) || {};
    const parts = kind === 'ap' ? [k, k] : k.split('||');
    rows.push({
      scope: kind, ap: parts[0], name: parts[1], group: meta.group || null,
      today: Math.round(t), baseline_avg: Math.round(avg),
      change_pct: avg > 0 ? Math.round(((t - avg) / avg) * 100) : null,
      _avg: avg,
    });
  }
  return rows;
}
const clean = r => { const { _avg, ...rest } = r; return rest; };
function classify(rows) {
  const up = rows.filter(r => r.change_pct !== null && r.change_pct >= PCT_UP && r.today >= MIN_VOLUME)
    .sort((a, b) => (b.today - b._avg) - (a.today - a._avg)).slice(0, TOP_UP).map(clean);
  const down = rows.filter(r => r.change_pct !== null && r.change_pct <= -PCT_DOWN && r._avg >= MIN_VOLUME)
    .sort((a, b) => (b._avg - b.today) - (a._avg - a.today)).slice(0, TOP_DOWN).map(clean);
  const fresh = n > 0 ? rows.filter(r => r._avg === 0 && r.today >= MIN_VOLUME)
    .sort((a, b) => b.today - a.today).slice(0, TOP_NEW).map(clean) : [];
  return { up, down, fresh };
}

const apRows = compare('ap').sort((a, b) => b.today - a.today);
const trends = {
